// Writes the generated files of src from what is on disk: index.ts (the package entry), component-names.ts (for the
// resolver) and globals.ts (opt-in global component types). Never edit them by hand: the hand-written exports are in
// src/core.ts, which index.ts re-exports. The files go through Prettier (scripts/generated.mjs).
// `--check` writes nothing and exits 1 when a committed generated file is stale.
import { readdirSync, existsSync, readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { dirname, join } from "node:path";
import { checking, reportStale, writeGenerated } from "../../../scripts/generated.mjs";

const root = join(dirname(fileURLToPath(import.meta.url)), "..", "src");
const components = existsSync(join(root, "components"))
  ? readdirSync(join(root, "components"), { withFileTypes: true })
      .filter((d) => d.isDirectory() && existsSync(join(root, "components", d.name, "index.ts")))
      .map((d) => d.name)
      .sort()
  : [];
const composables = existsSync(join(root, "composables"))
  ? readdirSync(join(root, "composables"))
      .filter((f) => f.endsWith(".ts") && !f.endsWith(".test.ts"))
      .map((f) => f.slice(0, -3))
      .sort()
  : [];

// A composable's exports are public unless marked `@internal`: in the JSDoc right before the export, or with a first line
// of `// @internal` for the whole file. The components share internal helpers (useDetails, useFieldControl) that are not
// part of the package's API, so they are named here one by one instead of with `export *`.
const exportLine =
  /(\/\*\*(?:(?!\*\/)[\s\S])*\*\/\s*)?^export\s+(?:declare\s+)?(?:async\s+)?(function|const|let|class|interface|type|enum)\s+([A-Za-z0-9_$]+)/gm;
function composableExports(name) {
  const source = readFileSync(join(root, "composables", `${name}.ts`), "utf8").replaceAll("\r\n", "\n");
  if (source.startsWith("// @internal")) return [];
  if (/^export\s*(\{|\*)/m.test(source))
    throw new Error(
      `composables/${name}.ts re-exports; export each name where it is declared so gen-index can list it`,
    );
  const values = [];
  const types = [];
  for (const m of source.matchAll(exportLine)) {
    if (m[1]?.includes("@internal")) continue;
    (m[2] === "interface" || m[2] === "type" ? types : values).push(m[3]);
  }
  const from = `"./composables/${name}.js"`;
  return [
    ...(values.length ? [`export { ${values.join(", ")} } from ${from};`] : []),
    ...(types.length ? [`export type { ${types.join(", ")} } from ${from};`] : []),
  ];
}

const header = "// Generated by scripts/gen-index.mjs. Do not edit.\n";

await writeGenerated(
  join(root, "index.ts"),
  `${header}import "./icons/builtin.js"; // registers the built-in icon set, with or without the plugin
export * from "./core.js"; // the hand-written exports: plugin, config, messages, icons, themes
${composables.flatMap(composableExports).join("\n")}
${components.map((c) => `export * from "./components/${c}/index.js";`).join("\n")}
`,
);

const names = components
  .flatMap((c) =>
    [
      ...readFileSync(join(root, "components", c, "index.ts"), "utf8").matchAll(
        /export \{ default as (E[A-Za-z0-9]+) \}/g,
      ),
    ].map((m) => m[1]),
  )
  .sort();
await writeGenerated(
  join(root, "component-names.ts"),
  `${header}export const componentNames: ReadonlySet<string> = new Set([\n${names.map((n) => `  "${n}",\n`).join("")}]);\n`,
);
// Gives Volar and vue-tsc the global component types (<EButton> in a template after `app.component` registration).
// Opt-in, as `@eos-ui/vue/globals`: `createEos()` registers no components, so declaring them for every app would let a
// missing import pass the type check and fail at run time. `$e` is declared in plugin.ts, since the plugin always sets it.
await writeGenerated(
  join(root, "globals.ts"),
  `${header}// Opt-in types for components you register globally with \`app.component\`. Load them with
// \`import type {} from "@eos-ui/vue/globals"\` or \`"types": ["@eos-ui/vue/globals"]\` in tsconfig.json.
import type * as Library from "./index.js";

declare module "vue" {
  interface GlobalComponents {
${names.map((n) => `    ${n}: typeof Library.${n};\n`).join("")}  }
}

export {};
`,
);

reportStale("pnpm --filter @eos-ui/vue prepare:gen");
if (checking) console.log("generated files are up to date");
else console.log(`index.ts: ${components.length} components, ${composables.length} composables`);
